3	import (
4		"errors"
5		"slices"
6		"strings"
7		"testing"
8	
9		"github.com/anthnel/devdesk/internal/ui/testutil"
10	)
11	
12	// DEVDESK-307 (IS-09), step 1: ← and esc on tags go back to where the tag
13	// table was opened from, level 1 (untouched, no new search) when → opened it,
14	// the search form otherwise.
15	
16	var backKeys = []string{"left", "esc"}
17	
18	// levelOneSnapshot is what the tests compare before → and after the way back.
19	type levelOneSnapshot struct {
20		names  []string
21		cursor int
22		images int
23	}
24	
25	func snapshotLevelOne(m Model) levelOneSnapshot {
26		b := m.registryBrowser
27		return levelOneSnapshot{lvl1Names(m), b.searchTable.Cursor(), len(b.images)}
28	}
29	
30	// c.1: back from tags opened with → shows level 1 as it was, with no request.
31	func TestBackFromRightTagsReturnsToLevelOne(t *testing.T) {
32		for _, key := range backKeys {
33			t.Run(key, func(t *testing.T) {
34				withFullTagRecorder(t)
35				fake := &fakeSearcher{}
36				withImageSearcher(t, fake)
37				m := selectLevelOneRow(t, drillRows(t), "hub", "library/nginx")
38				before := snapshotLevelOne(m)
39				searches := fake.calls()
40	
41				m, _, _ = pressRight(t, m)
42				if m.registryBrowser.state != browserStateTags {
43					t.Fatalf("state = %d after →, want tags", m.registryBrowser.state)
44				}
45				m, cmd := step(t, m, testutil.Key(key))
46	
47				b := m.registryBrowser
48				if b.state != browserStateImages {
49					t.Fatalf("state = %d after %s, want level 1 (browserStateImages)", b.state, key)
50				}
51				if cmd != nil {
52					t.Errorf("Cmd = %T, want nil (no new request)", testutil.Msg(cmd))
53				}
54				if got := snapshotLevelOne(m); !slices.Equal(got.names, before.names) || got.cursor != before.cursor || got.images != before.images {
55					t.Errorf("level 1 = %+v, want %+v", got, before)
56				}
57				if fake.calls() != searches {
58					t.Errorf("searches = %d, want %d", fake.calls(), searches)
59				}
60				if b.InEditMode() {
61					t.Error("InEditMode() is true at level 1")
62				}
63				// Level 1's table owns the keys again, the tag table does not.
64				m = feed(t, m, testutil.Key("home"), testutil.Key("down"))
65				if got := m.registryBrowser.searchTable.Cursor(); got != 1 {
66					t.Errorf("cursor after home, down = %d, want 1: the level 1 table is not focused", got)
67				}
68			})
69		}
70	}
71	
72	// c.1: the confirmed query, the order and the cursor survive the round trip.
73	func TestBackToLevelOneKeepsItsFilterAndOrder(t *testing.T) {
74		for _, key := range backKeys {
75			t.Run(key, func(t *testing.T) {
76				withFullTagRecorder(t)
77				m := drillRows(t)
78				m = feed(t, m, testutil.Key("/"))
79				m = feed(t, m, testutil.Type("ngi")...)
80				m = feed(t, m, testutil.Key("enter"), testutil.Key("home"), testutil.Key("down"))
81				b := m.registryBrowser
82				if got := b.searchTable.FilterBar().SearchQuery(); got != "ngi" {
83					t.Fatalf("query = %q, want ngi", got)
84				}
85				before := snapshotLevelOne(m)
86				if before.cursor != 1 {
87					t.Fatalf("cursor = %d, want the 2nd visible row", before.cursor)
88				}
89	
90				m, _, _ = pressRight(t, m)
91				m = feed(t, m, testutil.Key(key))
92	
93				b = m.registryBrowser
94				if b.state != browserStateImages {
95					t.Fatalf("state = %d, want level 1", b.state)
96				}
97				if got := b.searchTable.FilterBar().SearchQuery(); got != "ngi" {
98					t.Errorf("query = %q after the way back, want ngi", got)
99				}
100				if got := snapshotLevelOne(m); !slices.Equal(got.names, before.names) || got.cursor != before.cursor {
101					t.Errorf("level 1 = %+v, want %+v", got, before)
102				}
103				if !b.FilterIsVisible() {
104					t.Error("the level 1 filter bar is not shown")
105				}
106			})
107		}
108	}
109	
110	// c.2: leaving the tags drops the lot; its late answers change nothing.
111	func TestALateTagAnswerAfterBackIsIgnored(t *testing.T) {
112		for _, key := range backKeys {
113			t.Run(key, func(t *testing.T) {
114				m := afterRight(t) // → pressed, nothing answered yet
115				old := m.registryBrowser.gen
116				before := snapshotLevelOne(m)
117	
118				m = feed(t, m, testutil.Key(key))
119				b := m.registryBrowser
120				if b.state != browserStateImages {
121					t.Fatalf("state = %d, want level 1", b.state)
122				}
123				if b.gen == old {
124					t.Error("gen did not change")
125				}
126				if b.cancel != nil {
127					t.Error("the lot's cancel func is still held")
128				}
129	
130				late := failedTags(m, nil)
131				late.Gen, late.Err, late.Tags = old, nil, []string{"v1"}
132				failed := failedTags(m, errors.New("boom"))
133				failed.Gen = old
134				meta := MultiRegistryTagsMetaMsg{Gen: old, EntryKey: "hub", RegistryURL: "docker.io", Repo: "library/nginx"}
135				m = feed(t, m, late, failed, meta)
136	
137				b = m.registryBrowser
138				if b.state != browserStateImages {
139					t.Errorf("state = %d, a late answer moved the browser", b.state)
140				}
141				if b.pendingSearches != 0 {
142					t.Errorf("pendingSearches = %d, want 0", b.pendingSearches)
143				}
144				if _, loading := b.LoadingLabel(); loading {
145					t.Error("still loading after the way back")
146				}
147				if m.footer.IsSet() {
148					t.Errorf("footer = %q, want none", m.footer.Text())
149				}
150				if got := len(b.tagTable.Items()); got != 0 {
151					t.Errorf("tag rows = %d, want 0", got)
152				}
153				if got := snapshotLevelOne(m); !slices.Equal(got.names, before.names) || got.cursor != before.cursor {
154					t.Errorf("level 1 = %+v, want %+v", got, before)
155				}
156			})
157		}
158	}
