1	package ociresources
2	
3	import (
4		"errors"
5		"slices"
6		"strings"
7		"testing"
8	
9		"github.com/anthnel/devdesk/internal/ui/testutil"
10	)
11	
12	// DEVDESK-307 (IS-09), step 1: ← and esc on tags go back to where the tag
13	// table was opened from, level 1 (untouched, no new search) when → opened it,
14	// the search form otherwise.
15	
16	var backKeys = []string{"left", "esc"}
17	
18	// levelOneSnapshot is what the tests compare before → and after the way back.
19	type levelOneSnapshot struct {
20		names  []string
21		cursor int
22		images int
23	}
24	
25	func snapshotLevelOne(m Model) levelOneSnapshot {
26		b := m.registryBrowser
27		return levelOneSnapshot{lvl1Names(m), b.searchTable.Cursor(), len(b.images)}
28	}
29	
30	// c.1: back from tags opened with → shows level 1 as it was, with no request.
31	func TestBackFromRightTagsReturnsToLevelOne(t *testing.T) {
32		for _, key := range backKeys {
33			t.Run(key, func(t *testing.T) {
34				withFullTagRecorder(t)
35				fake := &fakeSearcher{}
36				withImageSearcher(t, fake)
37				m := selectLevelOneRow(t, drillRows(t), "hub", "library/nginx")
38				before := snapshotLevelOne(m)
39				searches := fake.calls()
40	
41				m, _, _ = pressRight(t, m)
42				if m.registryBrowser.state != browserStateTags {
43					t.Fatalf("state = %d after →, want tags", m.registryBrowser.state)
44				}
45				m, cmd := step(t, m, testutil.Key(key))
46	
47				b := m.registryBrowser
48				if b.state != browserStateImages {
49					t.Fatalf("state = %d after %s, want level 1 (browserStateImages)", b.state, key)
50				}
51				if cmd != nil {
52					t.Errorf("Cmd = %T, want nil (no new request)", testutil.Msg(cmd))
53				}
54				if got := snapshotLevelOne(m); !slices.Equal(got.names, before.names) || got.cursor != before.cursor || got.images != before.images {
55					t.Errorf("level 1 = %+v, want %+v", got, before)
56				}
57				if fake.calls() != searches {
58					t.Errorf("searches = %d, want %d", fake.calls(), searches)
59				}
60				if b.InEditMode() {
61					t.Error("InEditMode() is true at level 1")
62				}
63				// Level 1's table owns the keys again, the tag table does not.
64				m = feed(t, m, testutil.Key("home"), testutil.Key("down"))
65				if got := m.registryBrowser.searchTable.Cursor(); got != 1 {
66					t.Errorf("cursor after home, down = %d, want 1: the level 1 table is not focused", got)
67				}
68			})
69		}
70	}
71	
72	// c.1: the confirmed query, the order and the cursor survive the round trip.
73	func TestBackToLevelOneKeepsItsFilterAndOrder(t *testing.T) {
74		for _, key := range backKeys {
75			t.Run(key, func(t *testing.T) {
76				withFullTagRecorder(t)
77				m := drillRows(t)
78				m = feed(t, m, testutil.Key("/"))
79				m = feed(t, m, testutil.Type("ngi")...)
80				m = feed(t, m, testutil.Key("enter"), testutil.Key("home"), testutil.Key("down"))
81				b := m.registryBrowser
82				if got := b.searchTable.FilterBar().SearchQuery(); got != "ngi" {
83					t.Fatalf("query = %q, want ngi", got)
84				}
85				before := snapshotLevelOne(m)
86				if before.cursor != 1 {
87					t.Fatalf("cursor = %d, want the 2nd visible row", before.cursor)
88				}
89	
90				m, _, _ = pressRight(t, m)
91				m = feed(t, m, testutil.Key(key))
92	
93				b = m.registryBrowser
94				if b.state != browserStateImages {
95					t.Fatalf("state = %d, want level 1", b.state)
96				}
97				if got := b.searchTable.FilterBar().SearchQuery(); got != "ngi" {
98					t.Errorf("query = %q after the way back, want ngi", got)
99				}
100				if got := snapshotLevelOne(m); !slices.Equal(got.names, before.names) || got.cursor != before.cursor {
101					t.Errorf("level 1 = %+v, want %+v", got, before)
102				}
103				if !b.FilterIsVisible() {
104					t.Error("the level 1 filter bar is not shown")
105				}
106			})
107		}
108	}
109	
110	// c.2: leaving the tags drops the lot; its late answers change nothing.
111	func TestALateTagAnswerAfterBackIsIgnored(t *testing.T) {
112		for _, key := range backKeys {
113			t.Run(key, func(t *testing.T) {
114				m := afterRight(t) // → pressed, nothing answered yet
115				old := m.registryBrowser.gen
116				before := snapshotLevelOne(m)
117	
118				m = feed(t, m, testutil.Key(key))
119				b := m.registryBrowser
120				if b.state != browserStateImages {
121					t.Fatalf("state = %d, want level 1", b.state)
122				}
123				if b.gen == old {
124					t.Error("gen did not change")
125				}
126				if b.cancel != nil {
127					t.Error("the lot's cancel func is still held")
128				}
129	
130				late := failedTags(m, nil)
131				late.Gen, late.Err, late.Tags = old, nil, []string{"v1"}
132				failed := failedTags(m, errors.New("boom"))
133				failed.Gen = old
134				meta := MultiRegistryTagsMetaMsg{Gen: old, EntryKey: "hub", RegistryURL: "docker.io", Repo: "library/nginx"}
135				m = feed(t, m, late, failed, meta)
136	
137				b = m.registryBrowser
138				if b.state != browserStateImages {
139					t.Errorf("state = %d, a late answer moved the browser", b.state)
140				}
141				if b.pendingSearches != 0 {
142					t.Errorf("pendingSearches = %d, want 0", b.pendingSearches)
143				}
144				if _, loading := b.LoadingLabel(); loading {
145					t.Error("still loading after the way back")
146				}
147				if m.footer.IsSet() {
148					t.Errorf("footer = %q, want none", m.footer.Text())
149				}
150				if got := len(b.tagTable.Items()); got != 0 {
151					t.Errorf("tag rows = %d, want 0", got)
152				}
153				if got := snapshotLevelOne(m); !slices.Equal(got.names, before.names) || got.cursor != before.cursor {
154					t.Errorf("level 1 = %+v, want %+v", got, before)
155				}
156			})
157		}
158	}
159	
160	// H2: the tag filters do not outlive the tag table (the title would show a
161	// stale [alias] over level 1).
162	func TestBackFromTagsClearsTheTagFilters(t *testing.T) {
163		for _, key := range backKeys {
164			t.Run(key, func(t *testing.T) {
165				withFullTagRecorder(t)
166				m, _, _ := pressRight(t, selectLevelOneRow(t, drillRows(t), "hub", "library/nginx"))
167				// A → lot has one source, so `r` has no stop to cycle to: set the
168				// filter the way a multi-source table would have.
169				m.registryBrowser.registryFilter = resultFilter{entryKey: "hub"}
170				m = feed(t, m, testutil.Key(key))
171	
172				b := m.registryBrowser
173				if b.state != browserStateImages {
174					t.Errorf("state = %d, want level 1", b.state)
175				}
176				if !b.registryFilter.isEmpty() {
177					t.Errorf("registryFilter = %+v, want it cleared", b.registryFilter)
178				}
179				if b.tagsImage != "" {
180					t.Errorf("tagsImage = %q, want it cleared", b.tagsImage)
181				}
182				title := m.GetTitle()
183				if strings.Contains(title, "[") {
184					t.Errorf("title = %q, want no [registry] filter label", title)
185				}
186				if !strings.Contains(title, "nginx") {
187					t.Errorf("title = %q, want the typed text", title)
188				}
189			})
190		}
191	}
192	
193	// c.5: esc closes the open tag filter bar first, then goes back.
194	func TestEscClosesTheTagFilterFirst(t *testing.T) {
195		withFullTagRecorder(t)
196		m, _, _ := pressRight(t, selectLevelOneRow(t, drillRows(t), "hub", "library/nginx"))
197		m = feed(t, m, testutil.Key("/"))
198		m = feed(t, m, testutil.Type("v1")...)
199		m = feed(t, m, testutil.Key("esc"))
200		if m.registryBrowser.state != browserStateTags || m.registryBrowser.filterActive {
201			t.Fatalf("after the first esc: state %d, filterActive %v; want tags with the bar closed",
202				m.registryBrowser.state, m.registryBrowser.filterActive)
203		}
204		m = feed(t, m, testutil.Key("esc"))
205		if m.registryBrowser.state != browserStateImages {
206			t.Errorf("after the second esc: state = %d, want level 1", m.registryBrowser.state)
207		}
208	}
209	
210	// c.5: while the tag filter takes text, ← belongs to the text field.
211	func TestLeftWhileTypingTheTagFilterStaysInTheFilter(t *testing.T) {
212		withFullTagRecorder(t)
213		m, _, _ := pressRight(t, selectLevelOneRow(t, drillRows(t), "hub", "library/nginx"))
214		m = feed(t, m, testutil.Key("/"))
215		m = feed(t, m, testutil.Type("v1")...)
216		m = feed(t, m, testutil.Key("left"))
217		if m.registryBrowser.state != browserStateTags || !m.registryBrowser.filterActive {
218			t.Errorf("state %d, filterActive %v; want tags with the bar still open",
219				m.registryBrowser.state, m.registryBrowser.filterActive)
220		}
221	}
222	
223	// c.3: tags opened by full name go back to the form, on the Open Tags button.
224	func TestFullNameTagsGoBackToTheForm(t *testing.T) {
225		for _, key := range backKeys {
226			t.Run(key, func(t *testing.T) {
227				withImageSearcher(t, &fakeSearcher{})
228				withFullTagRecorder(t)
229				m := typeInto(t, browsingModel(t), "nginx")
230				b := m.registryBrowser
231				m = downTo(t, m, b.brFieldButton(1))
232				selected := checkedKeys(m)
233				m, cmd := step(t, m, testutil.Key("enter"))
234				m = feed(t, m, testutil.Msgs(cmd)...)
235				if m.registryBrowser.state != browserStateTags {
236					t.Fatalf("state = %d, want tags", m.registryBrowser.state)
237				}
238				old := m.registryBrowser.gen
239	
240				m = feed(t, m, testutil.Key(key))
241	
242				b = m.registryBrowser
243				if b.state != browserStateInput {
244					t.Fatalf("state = %d, want the form", b.state)
245				}
246				if b.focusedField != b.brFieldButton(1) {
247					t.Errorf("focus = %d, want the Open Tags button %d", b.focusedField, b.brFieldButton(1))
248				}
249				if got := b.repoInput.Value(); got != "nginx" {
250					t.Errorf("name = %q, want it kept", got)
251				}
252				if got := checkedKeys(m); !sameStrings(got, selected) {
253					t.Errorf("selection = %v, want %v", got, selected)
254				}
255				if b.gen == old {
256					t.Error("gen did not change: the tag lot was not abandoned (H1)")
257				}
258			})
259		}
260	}
261	
262	// A second → after the way back is a fresh lot on the new row.
263	func TestRightAgainAfterBackOpensANewLot(t *testing.T) {
264		rec := withFullTagRecorder(t)
265		m := selectLevelOneRow(t, drillRows(t), "hub", "library/nginx")
266		m, _, _ = pressRight(t, m)
267		m = feed(t, m, testutil.Key("left"))
268		if m.registryBrowser.state != browserStateImages {
269			t.Fatalf("state = %d, want level 1", m.registryBrowser.state)
270		}
271		rec.reset()
272	
273		m = selectLevelOneRow(t, m, "prod", "nginx")
274		m, _, _ = pressRight(t, m)
275	
276		b := m.registryBrowser
277		calls := rec.sorted()
278		if len(calls) != 1 || !strings.Contains(calls[0], "registry.example.com") || strings.Contains(calls[0], "library") {
279			t.Errorf("requests = %v, want one, to prod, for nginx", calls)
280		}
281		if b.state != browserStateTags || !b.tagsFromSearch {
282			t.Errorf("state %d, tagsFromSearch %v; want tags opened from level 1", b.state, b.tagsFromSearch)
283		}
284		if b.tagsImage != "nginx" {
285			t.Errorf("tagsImage = %q, want nginx", b.tagsImage)
286		}
287	}
